/*Rage 							--Index 1195*/ 		insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('1.0 Custom', 'Default', 'Rage', 						'After every square you move this turn immediately make one melee attack.  You may not make a Berserk attack on a turn you Rage.  This model''s ARM is reduced to 2B until her next activation.');
/*Summon Tiger					--Index 1196*/ 		insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('1.0 Custom', 'Default', 'Summon Tiger', 				'Place Tiger next to Amazon, and it is treated as an individual Hero for all purposes.  Amazon has one less action while Tiger is active.  Can only be summoned once per stage (8bit, 16bit, super), unless killed.  If killed may not be summoned again this game.  May be dismissed at anytime.  If dismissed, then any damage obtained carries over to the future summon.');
/*Marked for Death				--Index 1197*/ 		insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('1.0 Custom', 'Default', 'Marked for Death', 			'Pick target in LOS.  Until the end of this model''s next turn, it may attack the marked model using DEX despite LOS, or Range.  Only one target may be marked at a time.');
