/*Flaming Hands					--Index	1201*/ 		insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('1.0 Custom', 'Default', 'Flaming Hands',				'MAGIC, DANGEROUS, FIRE, SPRAY 2 +2 per additonal action used.');
