/*Meteor Shower					--Index	1203*/ 		insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('1.0 Custom', 'Default', 'Meteor Shower',				'MAGIC 8, DANGEROUS, BURST 3, KNOCKDOWN, STUN, FIRE, all affected models have a WAVE 1 attack centered on them.');

/*Dandyles Death				--Index	1204*/ 		insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('1.0 Custom', 'Default', 'Dandyles Death',			'Roll 1R, kill non-Boss, non-MiniBoss targets in LOS worth the total number of Skull points less than or equal to the stars rolled.');
/*Greater Shadow Demon			--Index	1205*/ 		insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('1.0 Custom', 'Default', 'Greater Shadow Demon',		'Place Shadow Demon next to Hand Fan and it is treated as an individual Hero for all purposes.  Hand Fan has one less action while Shadow Demon is active.  Can be dismissed and re-summoned anytime even if Shadow Demon is killed.');










